@Transactional
public void processOrder(Order order) {
    // Standard save: SQL is queued in the Persistence Context
    repository.save(order);

    // Force flush: SQL executes now. 
    // Useful if a DB trigger updates a 'status' column that we need immediately.
    repository.saveAndFlush(order);

    log.info("Database state is now synchronized with the entity");
}
